package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.DataNode;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.ParseErrorList;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.safety.Whitelist;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Cleaner_isValid_TriageGen2Test {

    private Cleaner cleaner;

    @Before
    public void setUp() {
        cleaner = new Cleaner(Whitelist.basic());
    }

    @Test
    public void testIsValidWithNullDocument() {
        assertTrue("Expected exception for null document", assertThrows(IllegalArgumentException.class, () -> cleaner.isValid(null)));
    }

    @Test
    public void testIsValidWithEmptyDocument() {
        Document emptyDocument = Document.createShell("");
        assertTrue(cleaner.isValid(emptyDocument));
    }

    @Test
    public void testIsValidWithSafeContent() {
        Document safeDocument = Document.createShell("http://example.com")
                .body()
                .appendElement("p")
                .text("Hello, world!");
        assertTrue(cleaner.isValid(safeDocument));
    }

    @Test
    public void testIsValidWithUnsafeContent() {
        Document unsafeDocument = Document.createShell("http://example.com")
                .body()
                .appendElement("script")
                .text("alert('XSS');");
        assertFalse(cleaner.isValid(unsafeDocument));
    }

    @Test
    public void testIsValidWithMixedContent() {
        Document mixedDocument = Document.createShell("http://example.com")
                .body()
                .appendElement("p")
                .text("Hello, world!")
                .appendElement("script")
                .text("alert('XSS');");
        assertFalse(cleaner.isValid(mixedDocument));
    }

    @Test
    public void testIsValidWithOnlyDiscardedNodes() {
        Document discardedDocument = Document.createShell("http://example.com")
                .body()
                .appendElement("script")
                .text("alert('XSS');");
        assertFalse(cleaner.isValid(discardedDocument));
    }

    @Test
    public void testIsValidWithOnlySafeNodes() {
        Document safeDocument = Document.createShell("http://example.com")
                .body()
                .appendElement("p")
                .text("Safe content");
        assertTrue(cleaner.isValid(safeDocument));
    }

    private <T> T assertThrows(Class<T> exceptionClass, Runnable runnable) {
        try {
            runnable.run();
            return null;
        } catch (Throwable throwable) {
            if (exceptionClass.isInstance(throwable)) {
                return exceptionClass.cast(throwable);
            } else {
                throw new AssertionError("Expected exception of type " + exceptionClass.getName() + " but got " + throwable.getClass().getName());
            }
        }
    }
}
